<?php
declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Integration\DeliveryQuote;
use CetechDeliveryEngine\Tests\Support\DataLifecycle\DataLifecycleProofDatabase as DB;
use CetechDeliveryEngine\Tests\Support\DeliveryQuote\{QuoteCartProofStack,QuoteProviderProofFixtures,QuoteProviderProofDatabase,QuoteCartProofDatabase,QuoteCartProofFixtures as CartF,QuoteLifecycleProofFactory as Factory,QuoteStorageProofWpdb,QuoteFixtures};
use CetechDeliveryEngine\Tests\Support\Operation\{OperationProofBarrier as Barrier,OperationProofProcess as Process};
use CetechDeliveryEngine\Application\DeliveryQuote\{CartQuoteSessionEnvelope as Envelope,NativeCartQuoteSessionStore as Store,QuotePreparationCommand};
use CetechDeliveryEngine\Domain\DeliveryQuote\{QuoteId,QuoteOwner};
use PHPUnit\Framework\Attributes\{DataProvider,Group};
use PHPUnit\Framework\TestCase;

/** New Q05 physical boundaries; native shopper/rendering qualification is separate. */
#[Group('quote-cart-real-db')]
final class DeliveryQuoteCartReferenceRealDatabaseTest extends TestCase {
	private \mysqli $database;
	private string $prefix;
	private array $factories=[];
	private array $stacks=[];
	private array $processes=[];
	private array $directories=[];
	private array $saved_globals=[];
	protected function setUp():void {
		foreach(['wpdb','blog_id'] as $key){$this->saved_globals[$key]=[array_key_exists($key,$GLOBALS),$GLOBALS[$key]??null];}
		$this->database=DB::connect();$this->prefix=DB::prefix();DB::install($this->database,$this->prefix);QuoteCartProofDatabase::install_sessions($this->database,$this->prefix);
		$GLOBALS['wpdb']=new QuoteStorageProofWpdb($this->database,$this->prefix);$GLOBALS['blog_id']=1;
	}
	protected function tearDown():void {
		foreach($this->processes as $p){$p->kill();}foreach($this->stacks as $s){$s->close_all();}foreach($this->factories as $f){$f->close_all();}foreach($this->directories as $d){Barrier::cleanup($d);}
		if(isset($this->database,$this->prefix)){DB::cleanup($this->database,$this->prefix);$this->database->close();}
		foreach($this->saved_globals as $key=>[$exists,$value]){if($exists){$GLOBALS[$key]=$value;}else{unset($GLOBALS[$key]);}}
	}
	private function stack(?callable $configure=null):QuoteCartProofStack { $s=new QuoteCartProofStack($this->prefix,null,$configure);$this->stacks[]=$s;return $s; }
	private function seed_provider():void {QuoteProviderProofFixtures::seed($this->database,$this->prefix);QuoteProviderProofDatabase::rate($this->database,$this->prefix);QuoteCartProofDatabase::install_native_receipt_tables($this->database,$this->prefix);}
	private function request():\CetechDeliveryEngine\Domain\Contracts\RequestContext{return \CetechDeliveryEngine\Domain\Contracts\RequestContext::create();}
	private function factory(?callable $configure=null):Factory{$f=new Factory($this->prefix);$f->configure=null===$configure?null:\Closure::fromCallable($configure);$this->factories[]=$f;return $f;}
	private function rows(string $suffix):array{$r=$this->database->query("SELECT * FROM `{$this->prefix}delivery_engine_{$suffix}` ORDER BY id");if(!$r instanceof \mysqli_result){throw new \RuntimeException('Native quote-cart rows refused.');}return $r->fetch_all(MYSQLI_ASSOC);}
	private function native_count(string $suffix):int{return (int)DB::scalar($this->database,"SELECT COUNT(*) FROM `{$this->prefix}delivery_engine_{$suffix}`");}
	private function directory():string{$d=Barrier::directory();$this->directories[]=$d;return $d;}
	private function worker(array $args):Process{$p=new Process([__DIR__.'/cart-reference-process-worker.php',json_encode(['prefix'=>$this->prefix]+$args,JSON_THROW_ON_ERROR)]);$this->processes[]=$p;return $p;}
	private function connection_signal(string $path,Process $p):int{Process::wait_for($path);$r=json_decode((string)file_get_contents($path),true,4,JSON_THROW_ON_ERROR);self::assertSame($p->pid(),$r['process_id']);self::assertGreaterThan(0,$r['connection_id']);return $r['connection_id'];}
	private function owner(string $session,?string $customer=null):QuoteOwner{return QuoteOwner::from_array(array_replace(CartF::owner()->facts(),['kind'=>null===$customer?'guest':'customer','principal_hash'=>QuoteFixtures::digest('principal:'.($customer??$session)),'session_hash'=>QuoteFixtures::digest('session:'.$session)]));}
	private function preparation(?QuoteOwner $owner=null,?string $token=null):QuotePreparationCommand {$owner??=CartF::owner();return QuotePreparationCommand::create($owner,\CetechDeliveryEngine\Tests\Support\DeliveryQuote\QuoteCartProofFixtures::draft($owner)->draft_digest(),$token??QuoteId::generate()->value(),'legacy_fixed_base_v1',1,'legacy_fixed_base_v1',1);}
	private function envelope(?QuoteOwner $owner=null,int $generation=1):Envelope{return Envelope::begin($this->preparation($owner),$generation,Factory::NOW+3600);}
	private function store(?Factory $factory=null,?QuoteOwner $owner=null,?callable $readiness=null):Store{$owner??=CartF::owner();return new Store($factory??$this->factory(),static fn(QuoteOwner $candidate,string $operation):bool=>$candidate->equals($owner),$readiness,'finite-q05-session-proof-secret',static fn():int=>Factory::NOW+3600);}
	private function customer_row():array{return DB::row($this->database,"SELECT * FROM `{$this->prefix}woocommerce_sessions` WHERE session_key='native-customer-row'");}
	public function test_actual_auxiliary_reference_has_a_separate_key_and_preserves_native_customer_bytes():void {
		$customer=$this->customer_row();$store=$this->store();$envelope=$this->envelope();self::assertTrue($store->compare_and_swap(CartF::owner(),null,$envelope));self::assertSame($envelope->to_private_json(),$store->load(CartF::owner())->to_private_json());self::assertNotSame('native-customer-row',$store->key_for(CartF::owner()));self::assertSame(32,strlen($store->key_for(CartF::owner())));self::assertSame($customer,$this->customer_row());self::assertCount(2,QuoteCartProofDatabase::sessions($this->database,$this->prefix));self::assertSame(0,$this->native_count('operation_records'));
	}
	public static function owner_pairs():array{return ['two guests'=>[null],'two carts of one customer'=>['one-customer']];}
	#[DataProvider('owner_pairs')]
	public function test_actual_reference_keys_isolate_two_sessions_even_for_one_customer(?string $customer):void {
		$a=$this->owner('cart-a',$customer);$b=$this->owner('cart-b',$customer);$as=$this->store(owner:$a);$bs=$this->store(owner:$b);$ae=$this->envelope($a);$be=$this->envelope($b);self::assertTrue($as->compare_and_swap($a,null,$ae));self::assertTrue($bs->compare_and_swap($b,null,$be));self::assertNotSame($as->key_for($a),$bs->key_for($b));self::assertSame($ae->to_private_json(),$as->load($a)->to_private_json());self::assertSame($be->to_private_json(),$bs->load($b)->to_private_json());self::assertFalse($bs->compare_and_swap($b,$be,$ae));self::assertSame($be->to_private_json(),$bs->load($b)->to_private_json());
	}
	public function test_late_old_generation_publication_cannot_overwrite_a_newer_reference():void {
		$store=$this->store();$begin=$this->envelope();self::assertTrue($store->compare_and_swap(CartF::owner(),null,$begin));$old=$begin->with_phase('failed');self::assertTrue($store->compare_and_swap(CartF::owner(),$begin,$old));$late=$this->envelope(generation:2);$new=$this->envelope(generation:2);self::assertTrue($store->compare_and_swap(CartF::owner(),$old,$new));self::assertFalse($store->compare_and_swap(CartF::owner(),$old,$late));self::assertSame($new->to_private_json(),$store->load(CartF::owner())->to_private_json());self::assertSame(0,$this->native_count('delivery_quotes'));
	}
	public static function session_table_conflicts():array{return ['wrong key type'=>['type'],'prefix-only unique key'=>['prefix'],'nontransactional engine'=>['engine']];}
	#[DataProvider('session_table_conflicts')]
	public function test_native_reference_table_conflict_refuses_without_rewriting_stored_bytes(string $conflict):void {
		$store=$this->store();$original=$this->envelope();self::assertTrue($store->compare_and_swap(CartF::owner(),null,$original));$before=QuoteCartProofDatabase::sessions($this->database,$this->prefix);$sql=match($conflict){'type'=>"ALTER TABLE `{$this->prefix}woocommerce_sessions` MODIFY session_key varchar(32) NOT NULL",'prefix'=>"ALTER TABLE `{$this->prefix}woocommerce_sessions` DROP INDEX session_key, ADD UNIQUE KEY session_key(session_key(8))",'engine'=>"ALTER TABLE `{$this->prefix}woocommerce_sessions` ENGINE=MyISAM"};DB::execute($this->database,$sql);self::assertFalse($store->compare_and_swap(CartF::owner(),$original,$original->with_phase('failed')));try{$store->load(CartF::owner());self::fail('Conflicting native reference metadata must refuse.');}catch(\RuntimeException){self::assertSame($before,QuoteCartProofDatabase::sessions($this->database,$this->prefix));}self::assertSame(0,$this->native_count('operation_records'));
	}
	public static function corrupted_values():array{return ['unknown mandatory format'=>['format'],'oversized reference'=>['size'],'malformed private JSON'=>['json']];}
	#[DataProvider('corrupted_values')]
	public function test_unknown_or_corrupt_private_reference_cannot_be_loaded_or_silently_replaced(string $conflict):void {
		$store=$this->store();$original=$this->envelope();self::assertTrue($store->compare_and_swap(CartF::owner(),null,$original));$key=$store->key_for(CartF::owner());$value=match($conflict){'format'=>str_replace('"format_version":1','"format_version":99',$original->to_private_json()),'size'=>str_repeat('x',Envelope::MAX_BYTES+1),'json'=>'{broken'};$value=$this->database->real_escape_string($value);DB::execute($this->database,"UPDATE `{$this->prefix}woocommerce_sessions` SET session_value='{$value}' WHERE session_key='{$key}'");$before=QuoteCartProofDatabase::sessions($this->database,$this->prefix);self::assertFalse($store->compare_and_swap(CartF::owner(),$original,$original->with_phase('failed')));try{$store->load(CartF::owner());self::fail('Unknown reference cannot load as legacy.');}catch(\RuntimeException){self::assertSame($before,QuoteCartProofDatabase::sessions($this->database,$this->prefix));}self::assertSame(0,$this->native_count('delivery_quotes'));
	}
	public function test_actual_refresh_creates_one_quote_and_confirmation_does_not_prepare_again():void {
		$this->seed_provider();$s=$this->stack();$token=QuoteId::generate()->value();$result=$s->service->refresh($token,0,$this->request());self::assertSame('review_required',$result->shopper_facts()['status']);self::assertSame(1,$s->environment->prepares);self::assertSame(1,$this->native_count('delivery_quotes'));self::assertSame(1,$this->native_count('operation_records'));self::assertSame(1,$this->native_count('operation_changes'));self::assertSame('consumed',$this->rows('delivery_quote_budget_windows')[2]['lease_state']);$opened=$s->sessions->load(CartF::owner());self::assertCount(1,$opened->rate_references());$component=$opened->original_issue()->context()->private_facts()['groups'][0]['component_key'];self::assertTrue($opened->rate_references()[0]->matches($opened->header(),$component,1));self::assertStringNotContainsString($opened->rate_references()[0]->public_fields()['component_handle'],json_encode($result->shopper_facts(),JSON_THROW_ON_ERROR));$result=$s->service->confirm(1,$this->request());self::assertSame('confirmed',$result->shopper_facts()['status']);self::assertSame(1,$s->environment->prepares);self::assertSame('accepted',$this->rows('delivery_quotes')[0]['state']);self::assertSame(2,$this->native_count('operation_records'));self::assertSame(2,$this->native_count('operation_changes'));$before=$this->rows('operation_changes');self::assertSame('confirmed',$s->service->confirm(1,$this->request())->shopper_facts()['status']);self::assertSame($before,$this->rows('operation_changes'));
	}

	public function test_two_os_processes_share_one_early_namespace_and_fresh_process_replay_never_prepares():void {
		$this->seed_provider();$d=$this->directory();$token=QuoteId::generate()->value();$a=$this->worker(['action'=>'refresh','token'=>$token,'generation'=>0,'prepare_ready'=>$d.'/ready','prepare_release'=>$d.'/release']);$this->connection_signal($d.'/ready',$a);self::assertSame(0,$this->native_count('operation_records'));self::assertSame(0,$this->native_count('delivery_quotes'));self::assertSame('granted',$this->rows('delivery_quote_budget_windows')[2]['lease_state']);
		try{$b=$this->worker(['action'=>'refresh','token'=>$token,'generation'=>0]);$br=$b->finish();self::assertNotSame($a->pid(),$br['process_id']);self::assertSame('unconfirmed',$br['status']);self::assertSame(0,$br['prepares']);self::assertSame(0,$br['source_captures']);self::assertSame(0,$br['native_reads']);}finally{Barrier::signal($d.'/release');}
		$ar=$a->finish();self::assertSame('review_required',$ar['status']);self::assertSame(1,$ar['prepares']);self::assertSame(1,$this->native_count('delivery_quotes'));self::assertSame(1,$this->native_count('operation_records'));self::assertSame(1,$this->native_count('operation_changes'));$budget=$this->rows('delivery_quote_budget_windows');self::assertSame([1,1,1],array_map(static fn(array $r):int=>(int)$r['attempt_count'],$budget));self::assertSame('consumed',$budget[2]['lease_state']);$quotes=$this->rows('delivery_quotes');$events=$this->rows('operation_changes');$records=$this->rows('operation_records');$sessions=QuoteCartProofDatabase::sessions($this->database,$this->prefix);$c=$this->worker(['action'=>'refresh','token'=>$token,'generation'=>0]);$cr=$c->finish();self::assertSame('review_required',$cr['status']);self::assertSame(0,$cr['prepares']);self::assertSame($quotes,$this->rows('delivery_quotes'));self::assertSame($events,$this->rows('operation_changes'));self::assertSame($records,$this->rows('operation_records'));self::assertSame($budget,$this->rows('delivery_quote_budget_windows'));self::assertSame($sessions,QuoteCartProofDatabase::sessions($this->database,$this->prefix));
	}
	public function test_delayed_old_generation_from_another_os_process_cannot_replace_current_reference():void {
		$s=$this->store();$begin=$this->envelope();self::assertTrue($s->compare_and_swap(CartF::owner(),null,$begin));$old=$begin->with_phase('failed');self::assertTrue($s->compare_and_swap(CartF::owner(),$begin,$old));$d=$this->directory();$a=$this->worker(['action'=>'cas','expected'=>$old->to_private_json(),'next'=>$this->envelope(generation:2)->to_private_json(),'dispatch_ready'=>$d.'/dispatch','dispatch_release'=>$d.'/release']);$this->connection_signal($d.'/dispatch',$a);$other=$this->owner('other-cart');$otherStore=$this->store(owner:$other);$otherEnvelope=$this->envelope($other);self::assertTrue($otherStore->compare_and_swap($other,null,$otherEnvelope));$customer=$this->customer_row();$new=$this->envelope(generation:2);try{self::assertTrue($s->compare_and_swap(CartF::owner(),$old,$new));}finally{Barrier::signal($d.'/release');}$r=$a->finish();self::assertFalse($r['cas']);self::assertSame(0,$r['lock_timeouts']);self::assertSame($new->to_private_json(),$s->load(CartF::owner())->to_private_json());self::assertSame($otherEnvelope->to_private_json(),$otherStore->load($other)->to_private_json());self::assertSame($customer,$this->customer_row());
	}

	public static function early_denials():array{return ['session quota'=>['session_minute',20],'site quota'=>['site_minute',200],'current pause'=>['pause',0],'schema downgrade'=>['schema',0]];}
	#[DataProvider('early_denials')]
	public function test_actual_early_denial_precedes_all_source_native_provider_and_c03_work(string $kind,int $limit):void {
		$s=$this->stack();if($limit>0){$r=$s->gate->admit($this->preparation(),\CetechDeliveryEngine\Application\DeliveryQuote\QuotePreparationAttempt::generate());self::assertSame('preparation_allowed',$r->status);DB::execute($this->database,"UPDATE `{$this->prefix}delivery_engine_delivery_quote_budget_windows` SET attempt_count={$limit},revision=revision+1 WHERE slot_kind='{$kind}'");}
		elseif('pause'===$kind){DB::insert_option($this->database,$this->prefix,\CetechDeliveryEngine\Infrastructure\Persistence\EmergencyControlStore::OPTION_NAME,\CetechDeliveryEngine\Domain\EmergencyControl\EmergencyControlState::record_json(1,'checkout_suspended',2,'operator_pause',9,Factory::NOW));}
		else{$name=\CetechDeliveryEngine\Core\Versioning\SchemaVersion::OPTION_NAME;DB::execute($this->database,"UPDATE `{$this->prefix}options` SET option_value='8' WHERE option_name='{$name}'");}
		$before=$this->rows('delivery_quote_budget_windows');$r=$s->service->refresh(QuoteId::generate()->value(),0,$this->request());self::assertSame('unavailable',$r->shopper_facts()['status']);self::assertSame(0,$s->environment->prepares);self::assertSame(0,$s->environment->source_captures());self::assertSame(0,$s->environment->native_reads());self::assertSame(0,$this->native_count('delivery_quotes'));self::assertSame(0,$this->native_count('operation_records'));self::assertSame(0,$this->native_count('operation_changes'));self::assertSame($before,$this->rows('delivery_quote_budget_windows'));self::assertSame('failed',$s->sessions->load(CartF::owner())->phase());
	}
	public function test_preparation_failure_terminates_only_its_original_lease_before_c03_and_replay_does_not_prepare():void {
		$s=$this->stack();$s->environment->before_prepare=static function():void{throw new \RuntimeException('Finite fixture refuses preparation.');};$token=QuoteId::generate()->value();self::assertSame('unavailable',$s->service->refresh($token,0,$this->request())->shopper_facts()['status']);self::assertSame(1,$s->environment->prepares);self::assertSame(0,$s->environment->source_captures());self::assertSame(0,$s->environment->native_reads());self::assertSame('terminated',$this->rows('delivery_quote_budget_windows')[2]['lease_state']);self::assertSame(0,$this->native_count('operation_records'));self::assertSame(0,$this->native_count('delivery_quotes'));$before=$this->rows('delivery_quote_budget_windows');self::assertSame('unavailable',$s->service->refresh($token,0,$this->request())->shopper_facts()['status']);self::assertSame(1,$s->environment->prepares);self::assertSame($before,$this->rows('delivery_quote_budget_windows'));
	}
	public function test_lost_session_commit_ack_is_recovered_from_fresh_native_read_without_second_write():void {
		$factory=$this->factory(static function($t):void{$t->fault_commit=1;$t->commit_fault='lost_ack';});$store=$this->store($factory);$envelope=$this->envelope();self::assertFalse($store->compare_and_swap(CartF::owner(),null,$envelope));self::assertSame(1,$factory->transports[0]->sent_commits);self::assertTrue($factory->sessions[0]->is_retired());$before=QuoteCartProofDatabase::sessions($this->database,$this->prefix);$fresh=$this->store();self::assertSame($envelope->to_private_json(),$fresh->load(CartF::owner())->to_private_json());self::assertFalse($fresh->compare_and_swap(CartF::owner(),null,$envelope));self::assertSame($before,QuoteCartProofDatabase::sessions($this->database,$this->prefix));self::assertSame(0,$this->native_count('operation_changes'));
