	public function test_lost_quote_commit_ack_keeps_original_staged_reference_and_fresh_os_retry_finishes_without_preparation():void {
		$this->seed_provider();$s=$this->stack(static function($t):void{$t->before=static function(string $sql,$transport):void{if(str_starts_with($sql,'INSERT INTO ')&&str_contains($sql,'delivery_engine_delivery_quotes')){$transport->fault_commit=2;$transport->commit_fault='lost_ack';}};});$token=QuoteId::generate()->value();self::assertSame('unconfirmed',$s->service->refresh($token,0,$this->request())->shopper_facts()['status']);self::assertSame('staged',$s->sessions->load(CartF::owner())->phase());self::assertSame(1,$this->native_count('delivery_quotes'));self::assertSame(1,$this->native_count('operation_changes'));$before=$this->rows('delivery_quotes');$events=$this->rows('operation_changes');$records=$this->rows('operation_records');$budget=$this->rows('delivery_quote_budget_windows');$w=$this->worker(['action'=>'retry','generation'=>1]);$r=$w->finish();self::assertSame('review_required',$r['status']);self::assertSame(0,$r['prepares']);self::assertSame('issued',$s->sessions->load(CartF::owner())->phase());self::assertSame($before,$this->rows('delivery_quotes'));self::assertSame($events,$this->rows('operation_changes'));self::assertSame(1,$this->native_count('operation_records'));$after=$this->rows('operation_records');self::assertSame($records[0]['completion_json'],$after[0]['completion_json']);self::assertSame($records[0]['audit_id'],$after[0]['audit_id']);self::assertSame('published',$after[0]['publication_state']);self::assertSame((int)$records[0]['row_version']+1,(int)$after[0]['row_version']);self::assertSame($budget,$this->rows('delivery_quote_budget_windows'));self::assertSame(1,$s->environment->prepares);
	}

	private function exact_session_wait(int $waiter,int $blocker):void {
		self::assertNotSame($waiter,$blocker);$table=$this->prefix.'woocommerce_sessions';$sql="SELECT COUNT(*) FROM information_schema.INNODB_LOCK_WAITS w JOIN information_schema.INNODB_LOCKS l ON l.lock_id=w.requested_lock_id JOIN information_schema.INNODB_TRX r ON r.trx_id=w.requesting_trx_id JOIN information_schema.INNODB_TRX b ON b.trx_id=w.blocking_trx_id WHERE l.lock_table=CONCAT('`',DATABASE(),'`.`{$table}`') AND r.trx_mysql_thread_id={$waiter} AND b.trx_mysql_thread_id={$blocker} AND r.trx_state='LOCK WAIT'";$end=microtime(true)+1.5;do{if((int)DB::scalar($this->database,$sql)>0){self::assertTrue(true);return;}$remaining=$end-microtime(true);if($remaining<=0)break;usleep((int)min(120000,ceil($remaining*1000000)));}while(microtime(true)<$end);self::fail('Exact second native reference owner did not wait on first owner.');
	}
	public function test_two_native_session_cas_owners_serialize_and_the_loser_cannot_overwrite():void {
		$store=$this->store();$original=$this->envelope();self::assertTrue($store->compare_and_swap(CartF::owner(),null,$original));$next=$original->with_phase('failed');$d=$this->directory();$a=$this->worker(['action'=>'cas','expected'=>$original->to_private_json(),'next'=>$next->to_private_json(),'lock_ready'=>$d.'/locked','lock_release'=>$d.'/release']);$blocker=$this->connection_signal($d.'/locked',$a);$b=$this->worker(['action'=>'cas','expected'=>$original->to_private_json(),'next'=>$next->to_private_json(),'dispatch_ready'=>$d.'/dispatch']);$waiter=$this->connection_signal($d.'/dispatch',$b);try{$this->exact_session_wait($waiter,$blocker);}finally{Barrier::signal($d.'/release');}$ar=$a->finish();$br=$b->finish();self::assertTrue($ar['cas']);self::assertFalse($br['cas']);self::assertSame(0,$ar['lock_timeouts']+$br['lock_timeouts']);self::assertSame(0,$ar['deadlocks']+$br['deadlocks']);self::assertSame($next->to_private_json(),$store->load(CartF::owner())->to_private_json());
	}
