	public static function changed_current_cart():array{return ['quantity'=>['quantity'],'current tariff'=>['rate'],'other owner'=>['owner']];}
	#[DataProvider('changed_current_cart')]
	public function test_current_cart_or_source_change_refuses_old_confirmation_and_keeps_recorded_history(string $kind):void {
